import * as React from 'react';
import { cn } from '@/lib/utils';
import { Input } from '../input/Input';
import { Textarea } from '../textarea/Textarea';
import { Select } from '../select/Select';

export type InputGroupProps = React.HTMLAttributes<HTMLDivElement>;

type CloneableProps = Record<string, unknown>;

const isNestedField = (child: React.ReactNode): child is React.ReactElement<CloneableProps> =>
  React.isValidElement(child) && (child.type === Input || child.type === Textarea || child.type === Select);

/**
 * Composite input shell: one outer outline wraps the addons and the
 * field itself. Nested inputs shed their own border/ring — focus and
 * the outline belong to the group, so left/right addons read as flush
 * parts of a single control (the outline doubles as the affordance).
 *
 * id / aria-describedby / aria-invalid arriving from FormField are
 * forwarded to the nested field, because a label's htmlFor must
 * resolve to the editable control, not the shell div.
 */
const InputGroup = React.forwardRef<HTMLDivElement, InputGroupProps>(
  ({ id, 'aria-describedby': describedBy, 'aria-invalid': invalid, className, children, ...props }, ref) => {
    let wiredChildren = children;

    if (id !== undefined || describedBy !== undefined || invalid !== undefined) {
      const items = React.Children.toArray(children);
      const fieldIndex = items.findIndex(isNestedField);
      if (fieldIndex !== -1) {
        const field = items[fieldIndex];
        items[fieldIndex] = isNestedField(field)
          ? React.cloneElement(field, {
              ...(id !== undefined && { id }),
              ...(describedBy !== undefined && { 'aria-describedby': describedBy }),
              ...(invalid !== undefined && { 'aria-invalid': invalid }),
            })
          : field;
        wiredChildren = items;
      } else {
        // No recognizable field (custom children) — keep the wiring on the shell.
        props = {
          ...props,
          ...(id !== undefined && { id }),
          ...(describedBy !== undefined && { 'aria-describedby': describedBy }),
          ...(invalid !== undefined && { 'aria-invalid': invalid }),
        };
      }
    }

    return (
      <div
        ref={ref}
        data-slot="input-group"
        className={cn(
          'flex h-10 w-full items-center overflow-hidden rounded-md border border-input bg-background',
          'ring-offset-background focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2',
          // The group's outline is the only outline: force-strip every
          // nested field's border, radius, ring, shadow and UA focus outline.
          // Important flags defeat both the component's own utilities
          // (Input ships `border` + `focus-visible:ring-2`) and browser
          // defaults — no seams appear where an addon sits flush.
          '[&_input]:h-full [&_input]:min-w-0 [&_input]:flex-1 [&_input]:rounded-none [&_input]:px-3 [&_input]:py-2',
          '[&_input]:!border-0 [&_input]:!bg-transparent [&_input]:!shadow-none [&_input]:!outline-none [&_input]:!ring-0 [&_input]:!ring-offset-0',
          '[&_textarea]:!border-0 [&_textarea]:!rounded-none [&_textarea]:!bg-transparent [&_textarea]:!shadow-none [&_textarea]:!outline-none [&_textarea]:!ring-0 [&_textarea]:!ring-offset-0',
          '[&_select]:!border-0 [&_select]:!rounded-none [&_select]:!bg-transparent [&_select]:!shadow-none [&_select]:!outline-none [&_select]:!ring-0 [&_select]:!ring-offset-0',
          '[&_input:disabled]:cursor-not-allowed',
          className
        )}
        {...props}
      >
        {wiredChildren}
      </div>
    );
  }
);
InputGroup.displayName = 'InputGroup';

export type InputGroupAddonProps = React.HTMLAttributes<HTMLDivElement> & {
  /** Edge the addon hugs (flush against the group outline). */
  side?: 'left' | 'right';
  /** 'muted' paints a light-gray surface; 'ghost' keeps the group background. */
  variant?: 'ghost' | 'muted';
};

/**
 * Flush icon/text/button slot inside an InputGroup. Addons carry their
 * own padding on the outer edge only — the nested field's padding
 * supplies the gap toward the middle, so content stays on one rhythm.
 */
const InputGroupAddon = React.forwardRef<HTMLDivElement, InputGroupAddonProps>(
  ({ side = 'left', variant = 'ghost', className, ...props }, ref) => (
    <div
      ref={ref}
      data-slot="input-group-addon"
      data-side={side}
      className={cn(
        'flex shrink-0 select-none items-center self-stretch px-3 text-sm text-muted-foreground',
        variant === 'muted' && 'bg-muted',
        className
      )}
      {...props}
    />
  )
);
InputGroupAddon.displayName = 'InputGroupAddon';

export { InputGroup, InputGroupAddon };

{
  "id": "input-group",
  "name": "InputGroup",
  "tier": "molecule",
  "description": "Composite input shell with flush left/right addons (icons, units, buttons) behind one outer outline; the nested field sheds its own border so the group reads as a single control.",
  "designIntent": "Search fields, URL/unit inputs, and inline actions need affixes that sit flush inside the field. InputGroup owns the combined border and focus ring (the outline doubles as the affordance) while addons stay visually part of the field: ghost addons keep the group background, muted addons paint a light gray, and nested inputs are stripped of their own chrome via descendant selectors.",
  "props": [
    {
      "name": "side",
      "type": "'left' | 'right'",
      "required": false,
      "description": "Edge the addon hugs (flush against the group outline).",
      "defaultValue": "left",
      "examples": [
        "left",
        "right"
      ]
    },
    {
      "name": "variant",
      "type": "'ghost' | 'muted'",
      "required": false,
      "description": "Addon surface: ghost keeps the group background, muted paints a light gray.",
      "defaultValue": "ghost",
      "examples": [
        "ghost",
        "muted"
      ]
    }
  ],
  "examples": [
    {
      "title": "URL field with unit affixes",
      "code": "<InputGroup>\n  <InputGroupAddon side=\"left\" variant=\"muted\">https://</InputGroupAddon>\n  <Input placeholder=\"example.com\" />\n  <InputGroupAddon side=\"right\" variant=\"muted\">.com</InputGroupAddon>\n</InputGroup>",
      "description": "Muted affixes carry the fixed parts of the value; only the middle is editable."
    },
    {
      "title": "Search with icon and action button",
      "code": "<InputGroup>\n  <InputGroupAddon side=\"left\" aria-hidden=\"true\"><SearchIcon size={16} /></InputGroupAddon>\n  <Input aria-label=\"Search\" placeholder=\"Search issues…\" />\n  <InputGroupAddon side=\"right\" variant=\"muted\">\n    <Button size=\"sm\" variant=\"ghost\">Go</Button>\n  </InputGroupAddon>\n</InputGroup>",
      "description": "Leading icon is decorative; the trailing button is the pseudo action indicator."
    },
    {
      "title": "Numeric input with currency suffix",
      "code": "<InputGroup>\n  <Input aria-label=\"Amount\" type=\"number\" defaultValue=\"10\" />\n  <InputGroupAddon side=\"right\" variant=\"muted\">PLN</InputGroupAddon>\n</InputGroup>",
      "description": "The unit sits flush right; the outline communicates editability."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't give nested inputs their own border",
      "explanation": "The group's outer border is the control outline. Inner borders create double lines and break the flush-addon look — strip them with the group (built in) or avoid nesting a bordered Input.",
      "example": "// Avoid: bordered input inside a bordered group\n<InputGroup><Input className=\"border\" /></InputGroup>\n\n// Prefer: let InputGroup strip the chrome\n<InputGroup><Input /></InputGroup>"
    },
    {
      "title": "Don't nest interactive elements without labels",
      "explanation": "Addon buttons live inside the field's focus-within region; they still need accessible names and must not steal the field's label association.",
      "example": "// Avoid\n<InputGroupAddon side=\"right\"><button>×</button></InputGroupAddon>\n\n// Prefer\n<InputGroupAddon side=\"right\">\n  <Button aria-label=\"Clear input\" variant=\"ghost\">×</Button>\n</InputGroupAddon>"
    }
  ],
  "accessibility": [
    {
      "feature": "Single focus stop",
      "implementation": "Focus ring renders on the group via focus-within; nested inputs keep keyboard focus and their label association (htmlFor/id still targets the input)",
      "userRequirements": "Label the INPUT (FormField/Input aria-label), not the group"
    },
    {
      "feature": "Decorative affixes",
      "implementation": "Purely decorative icons/text in addons should carry aria-hidden or the input's aria-label should include the unit",
      "userRequirements": "Mark decorative addons aria-hidden; name units the field's accessible name when they change meaning (e.g. aria-label=\"Amount in PLN\")"
    },
    {
      "feature": "Disabled state",
      "implementation": "Nested input's disabled styling applies; addons are independent — disable buttons inside them yourself",
      "userRequirements": "Disable addon buttons when the field is disabled"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Addon text",
      "guidelines": [
        "Keep affixes short (units, schemes, TLDs)",
        "Use the same casing the user would type",
        "Prefer icons for actions, text for value parts"
      ],
      "goodExamples": [
        "https://",
        ".com",
        "PLN",
        "/month"
      ],
      "badExamples": [
        "Enter the protocol here",
        "domain suffix"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Input / Textarea / Select",
      "relationship": "The nested field is the editable region; InputGroup strips its border/ring automatically",
      "example": "<InputGroup><InputGroupAddon side=\"left\">@</InputGroupAddon><Input /></InputGroup>"
    },
    {
      "component": "FormField",
      "relationship": "Wrap the whole group when it needs a persistent label or error",
      "example": "<FormField label=\"Search\"><InputGroup>…</InputGroup></FormField>"
    },
    {
      "component": "Button",
      "relationship": "Buttons inside addons are the action affordance — ghost/variant='ghost' keeps the flush look",
      "example": "<InputGroupAddon side=\"right\"><Button size=\"sm\">Go</Button></InputGroupAddon>"
    }
  ],
  "relatedComponents": [
    "Input",
    "FormField",
    "Search",
    "Button"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.8.0",
  "sourceDir": "input-group",
  "exportName": "InputGroup"
}
